import { FUNDAMENTALS_ADDITIONAL_SEEDS } from './fundamentalsAdditions';

export interface InterviewCatalogItem {
  id: string;
  question: string;
  primaryRole: string;
  roles: string[];
  category: string;
  format: 'knowledge' | 'scenario' | 'system-design' | 'project';
  difficulty: 'easy' | 'medium' | 'hard';
  tags: string[];
  keyPoints: string[];
  referenceAnswer: string;
  followUps: string[];
}

type Seed = readonly [
  question: string,
  category: string,
  format: InterviewCatalogItem['format'],
  difficulty: InterviewCatalogItem['difficulty'],
  keyPoints: readonly [string, string, string],
  answerCore: string,
  followUp: string,
];

const normalizeForCatalogId = (value: string): string => value
  .normalize('NFKC')
  .toLocaleLowerCase('zh-CN')
  .replace(/[^\p{Script=Han}\p{Letter}\p{Number}]+/gu, '');

export function buildEngineeringCatalogId(primaryRole: string, question: string, _legacyIndex?: number): string {
  const input = `${primaryRole}:${normalizeForCatalogId(question)}`;
  let hash = 0x811c9dc5;
  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return `engineering-${primaryRole}-${(hash >>> 0).toString(36).padStart(7, '0')}`;
}

const buildRoleCatalog = (
  primaryRole: string,
  seeds: readonly Seed[],
  relatedRoles: readonly string[] = [],
): InterviewCatalogItem[] => seeds.map((seed, index) => {
  const [question, category, format, difficulty, keyPoints, answerCore, followUp] = seed;
  return {
    id: buildEngineeringCatalogId(primaryRole, question, index + 1),
    question,
    primaryRole,
    roles: [...new Set([primaryRole, ...relatedRoles])],
    category,
    format,
    difficulty,
    tags: [primaryRole, category, ...keyPoints.slice(0, 2)],
    keyPoints: [...keyPoints],
    referenceAnswer: answerCore,
    followUps: [followUp],
  };
});

const extendSeedAnswers = (seeds: readonly Seed[], extensions: readonly string[]): readonly Seed[] => {
  if (seeds.length !== extensions.length) {
    throw new Error(`面试题答案扩写数量不匹配：${seeds.length}/${extensions.length}`);
  }
  return seeds.map((seed, index) => [
    seed[0],
    seed[1],
    seed[2],
    seed[3],
    seed[4],
    `${seed[5]}${extensions[index]}`,
    seed[6],
  ] as const);
};

