const completeRoleSeeds = (baseSeeds: readonly Seed[], supplementSeeds: readonly Seed[]): readonly Seed[] => {
  const requiredSupplementCount = 50 - baseSeeds.length;
  if (requiredSupplementCount < 0 || supplementSeeds.length < requiredSupplementCount) {
    throw new Error(`工程岗位题库数量不完整：${baseSeeds.length}+${supplementSeeds.length}`);
  }
  return [...baseSeeds, ...supplementSeeds.slice(0, requiredSupplementCount)];
};

const completeBackendSeeds = completeRoleSeeds(backendSeeds, backendSupplementSeeds);
const completeFrontendSeeds = completeRoleSeeds(frontendSeeds, frontendSupplementSeeds);
const completeClientSeeds = completeRoleSeeds(clientSeeds, clientSupplementSeeds);
const completeDataEngineeringSeeds = completeRoleSeeds(dataEngineeringSeeds, dataEngineeringSupplementSeeds);
const completeTestDevelopmentSeeds = completeRoleSeeds(testDevelopmentSeeds, testDevelopmentSupplementSeeds);
const completeSreDevopsSeeds = completeRoleSeeds(sreDevopsSeeds, sreDevopsSupplementSeeds);
const completeSecuritySeeds = completeRoleSeeds(securitySeeds, securitySupplementSeeds);
const completeEmbeddedSeeds = completeRoleSeeds(embeddedSeeds, embeddedSupplementSeeds);
if (FUNDAMENTALS_ADDITIONAL_SEEDS.length < 25) {
  throw new Error(`计算机基础补充题库数量不完整：${FUNDAMENTALS_ADDITIONAL_SEEDS.length}`);
}
const selectedFundamentalsAdditions = FUNDAMENTALS_ADDITIONAL_SEEDS;

export const ENGINEERING_INTERVIEW_ANSWER_CORES: readonly string[] = [
  ...completeBackendSeeds,
  ...completeFrontendSeeds,
  ...completeClientSeeds,
  ...completeDataEngineeringSeeds,
  ...completeTestDevelopmentSeeds,
  ...completeSreDevopsSeeds,
  ...completeSecuritySeeds,
  ...completeEmbeddedSeeds,
  ...fundamentalsSeeds,
].map((seed) => seed[5]).concat(selectedFundamentalsAdditions.map((item) => item.referenceAnswer));

